import json
p="/home/ubuntu/.claude/projects/-home-ubuntu------AI-powered-Network-Diagnostics/0a221d45-450a-4689-b775-0e280499b0b5.jsonl"
rows=[json.loads(l) for l in open(p) if l.strip()]
print("total rows", len(rows))
# print last 40 entries summary
import json as j
def brief(r):
    t=r.get("type")
    m=r.get("message",{})
    if t=="assistant":
        parts=[]
        for b in m.get("content",[]):
            if b.get("type")=="text": parts.append("TEXT:"+b["text"][:400])
            elif b.get("type")=="tool_use": parts.append("TOOL:"+b.get("name","")+" "+j.dumps(b.get("input",{}),ensure_ascii=False)[:300])
        return t, " | ".join(parts)
    if t=="user":
        c=m.get("content")
        if isinstance(c,str): return t,c[:300]
        if isinstance(c,list):
            out=[]
            for b in c:
                if b.get("type")=="text": out.append("TEXT:"+b["text"][:300])
                elif b.get("type")=="tool_result":
                    cc=b.get("content")
                    s=cc if isinstance(cc,str) else j.dumps(cc,ensure_ascii=False)
                    out.append("RES:"+s[:300])
            return t," | ".join(out)
    return t,""
for i,r in enumerate(rows[-60:]):
    tt,b=brief(r)
    print("="*60)
    print(len(rows)-60+i, tt)
    print(b)
EOF

