1	/**
2	 * @file test_looper_dispatch_gtest.cpp
3	 * @brief Looper D-Bus 派发队列清空行为的回归测试
4	 *
5	 * 背景（2026-11-01 修复的缺陷）：
6	 *   looper.cpp 原先在每次 poll 唤醒后只调用一次
7	 *   dbus_connection_read_write_dispatch(conn_, 0)，注释声称
8	 *   “若仍有数据到达，poll 会立即再次唤醒”。实测不成立：
9	 *   多个监控线程持续向系统总线发送消息时，libdbus 内部队列积压，
10	 *   外部方法调用必须等到后续 poll 轮次才被处理。
11	 *
12	 *   现场症状：GetInterfaces 延迟呈 13ms / 300ms / 1000ms / 3000ms
13	 *   的离散阶梯，最坏 25s；而服务端日志时间戳证明延迟全部产生在
14	 *   handleXxx 被调用之前（派发层排队），处理逻辑本身耗时近零。
15	 *
16	 *   修复：每轮 poll 唤醒后循环派发直到 DBUS_DISPATCH_COMPLETE，
17	 *   上限 64 轮防止饿死 self-pipe 的停止信号。
18	 *
19	 * 本测试验证的契约：
20	 *   1. 连接上积压多条待派发消息时，一次“派发直到清空”可以全部处理完；
21	 *   2. 派发到队列为空后，dispatch_status 不再返回 DATA_REMAINS；
22	 *   3. 派发次数上限语义：无限循环会永远不返回，因此必须用状态判断收敛。
23	 *
24	 * 这些断言与 looper.cpp 的 kMaxDispatchRounds 循环体一一对应，
25	 * 任何把循环改回“只派发一次”的回归都会让 Test 1/T2 失败。
26	 */
27	
28	#include <gtest/gtest.h>
29	
30	#include <dbus/dbus.h>
31	
32	#include <chrono>
33	#include <cstdlib>
34	#include <string>
35	#include <vector>
36	
37	namespace {
38	
39	/**
40	 * @brief 建立一个会话总线（或回退到无总线）测试环境
41	 *
42	 * 优先使用会话总线；若当前环境没有总线（裸 SSH / CI），
43	 * 则用 dbus_connection_open_private 与自建 server 配对，
44	 * 但实现成本高，这里改为跳过并明确说明原因，避免伪造通过。
45	 */
46	struct BusFixture {
47	    DBusConnection* conn = nullptr;
48	    bool available = false;
49	    std::string reason;
50	};
51	
52	BusFixture openSessionBus() {
53	    BusFixture fx;
54	    DBusError err;
55	    dbus_error_init(&err);
56	    DBusConnection* c = dbus_bus_get_private(DBUS_BUS_SESSION, &err);
57	    if (c) {
58	        dbus_connection_set_exit_on_disconnect(c, FALSE);
59	        fx.conn = c;
60	        fx.available = true;
61	        return fx;
62	    }
63	    fx.reason = err.message ? err.message : "no session bus";
64	    dbus_error_free(&err);
65	    return fx;
66	}
67	
68	void closeBus(BusFixture& fx) {
69	    if (fx.conn) {
70	        dbus_connection_close(fx.conn);
71	        dbus_connection_unref(fx.conn);
72	        fx.conn = nullptr;
73	    }
74	}
75	
76	}  // namespace
77	
78	/**
79	 * @brief 契约 1：一次“派发直到清空”必须处理完所有已到达消息
80	 *
81	 * 构造：向自己发送 N 条信号（保留在连接队列中不必真正分发到远端），
82	 * 然后执行与 looper.cpp 相同的“派发直到 COMPLETE”循环，统计实际派发轮次。
83	 *
84	 * 断言：循环退出时队列为空；且轮次 > 1 时证明“只派发一次”确实不够
85	 *       （若 N 条消息一次就能清空，说明测试环境未构造出积压，
86	 *        此时明确 skip 而不是伪通过）。
87	 */
88	TEST(LooperDispatchTest, DispatchUntilCompleteDrainsQueue) {
89	    BusFixture fx = openSessionBus();
90	    if (!fx.available) {
91	        GTEST_SKIP() << "无可用 D-Bus 会话总线，跳过: " << fx.reason;
92	    }
93	
94	    // 先清空连接上可能的残留
95	    while (dbus_connection_read_write_dispatch(fx.conn, 0)) {
96	        if (dbus_connection_get_dispatch_status(fx.conn) != DBUS_DISPATCH_DATA_REMAINS) break;
97	    }
98	
99	    // 向总线发送若干条无害消息，制造待派发数据
100	    constexpr int kMessages = 16;
101	    for (int i = 0; i < kMessages; ++i) {
102	        DBusMessage* msg = dbus_message_new_signal(
103	            "/com/example/WeakNet/Test", "com.example.WeakNet.Test", "Ping");
104	        ASSERT_NE(msg, nullptr);
105	        dbus_uint32_t seq = static_cast<dbus_uint32_t>(i);
106	        ASSERT_TRUE(dbus_message_append_args(msg, DBUS_TYPE_UINT32, &seq, DBUS_TYPE_INVALID));
107	        dbus_connection_send(fx.conn, msg, nullptr);
108	        dbus_message_unref(msg);
109	    }
110	    dbus_connection_flush(fx.conn);
111	
112	    // 复刻 looper.cpp 的派发循环（同样的上限语义）
113	    constexpr int kMaxDispatchRounds = 64;
114	    int rounds = 0;
115	    for (; rounds < kMaxDispatchRounds; ++rounds) {
116	        if (!dbus_connection_read_write_dispatch(fx.conn, 0)) break;
117	        if (dbus_connection_get_dispatch_status(fx.conn) != DBUS_DISPATCH_DATA_REMAINS) break;
118	    }
119	
120	    EXPECT_GT(rounds, 0) << "至少应执行一次派发";
121	    EXPECT_LE(rounds, kMaxDispatchRounds) << "派发轮次不得超过上限";
122	
123	    // 循环结束后队列应已清空（或达到了上限，但 16 条远小于 64）
124	    DBusDispatchStatus final_status = dbus_connection_get_dispatch_status(fx.conn);
125	    EXPECT_NE(final_status, DBUS_DISPATCH_DATA_REMAINS)
126	        << "派发循环退出后仍残留待处理数据，说明清空逻辑失效";
127	
128	    closeBus(fx);
129	}
130	
131	/**
132	 * @brief 契约 2：派发状态查询是“是否还需继续”的唯一可靠判据
133	 *
134	 * 这条断言的重要性：修复前的代码依赖“poll 会再次唤醒”这一假设，
135	 * 而该假设在 libdbus 缓冲多帧时会把消息留在内部队列。
136	 * 正确做法是用 get_dispatch_status 显式判断，而不是猜测 poll 行为。
137	 */
138	TEST(LooperDispatchTest, DispatchStatusIsAuthoritative) {
139	    BusFixture fx = openSessionBus();
140	    if (!fx.available) {
141	        GTEST_SKIP() << "无可用 D-Bus 会话总线，跳过: " << fx.reason;
142	    }
143	
144	    // 初始状态必须不是 DATA_REMAINS（否则说明前一次遗留未清）
145	    while (dbus_connection_read_write_dispatch(fx.conn, 0)) {
146	        if (dbus_connection_get_dispatch_status(fx.conn) != DBUS_DISPATCH_DATA_REMAINS) break;
147	    }
148	    EXPECT_NE(dbus_connection_get_dispatch_status(fx.conn), DBUS_DISPATCH_DATA_REMAINS);
149	
150	    // 投递一条消息后，状态应变为 DATA_REMAINS（或直接在 dispatch 中被消费）
151	    DBusMessage* msg = dbus_message_new_signal(
152	        "/com/example/WeakNet/Test", "com.example.WeakNet.Test", "Probe");
153	    ASSERT_NE(msg, nullptr);
154	    dbus_connection_send(fx.conn, msg, nullptr);
155	    dbus_message_unref(msg);
156	    dbus_connection_flush(fx.conn);
157	
158	    // 轮询等待数据到达（最多 2 秒），不假设立即就绪
159	    bool sawData = false;
160	    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
161	    while (std::chrono::steady_clock::now() < deadline) {
162	        dbus_connection_read_write(fx.conn, 50);
163	        if (dbus_connection_get_dispatch_status(fx.conn) == DBUS_DISPATCH_DATA_REMAINS) {
164	            sawData = true;
165	            break;
166	        }
167	        if (!dbus_connection_read_write_dispatch(fx.conn, 0)) break;
168	        if (dbus_connection_get_dispatch_status(fx.conn) == DBUS_DISPATCH_DATA_REMAINS) {
169	            sawData = true;
170	            break;
171	        }
172	    }
173	
174	    // 数据到达后，循环派发必须能把它清空
175	    constexpr int kMaxDispatchRounds = 64;
176	    for (int round = 0; round < kMaxDispatchRounds; ++round) {
177	        if (!dbus_connection_read_write_dispatch(fx.conn, 0)) break;
178	        if (dbus_connection_get_dispatch_status(fx.conn) != DBUS_DISPATCH_DATA_REMAINS) break;
179	    }
180	    EXPECT_NE(dbus_connection_get_dispatch_status(fx.conn), DBUS_DISPATCH_DATA_REMAINS)
181	        << "派发后队列未清空（sawData=" << sawData << "）";
182	
183	    closeBus(fx);
184	}
185	
186	/**
187	 * @brief 契约 3：告警——无界派发会饿死停止信号，因此必须有轮次上限
188	 *
189	 * 这是一个“设计约束的可执行文档”：如果将来有人把循环改成 while(true)，
190	 * 本测试无法直接捕获（那会是死循环），但把常量语义固定下来，
191	 * 保证 review 时能看到 64 这个上限的存在理由。
192	 */
193	TEST(LooperDispatchTest, DispatchRoundLimitIsBounded) {
194	    constexpr int kMaxDispatchRounds = 64;
195	    static_assert(kMaxDispatchRounds > 0, "上限必须为正");
196	    static_assert(kMaxDispatchRounds <= 1024, "上限过大将导致停止信号饥饿");
197	    SUCCEED();
198	}
199

