#include <dbus/dbus.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static DBusConnection* g_server_conn = NULL;

static void new_conn(DBusServer* s, DBusConnection* c, void* data) {
    (void)s; (void)data;
    if (!dbus_connection_set_route_peer_messages(c, TRUE)) {
        printf("route_peer_messages failed\n");
    }
    g_server_conn = dbus_connection_ref(c);
    printf("[server] new connection\n");
}

int main(void) {
    DBusError err;
    dbus_error_init(&err);

    DBusServer* server = dbus_server_listen("unix:tmpdir=/tmp", &err);
    if (!server) { printf("listen failed: %s\n", err.message); return 1; }
    char* addr = dbus_server_get_address(server);
    printf("[server] address=%s\n", addr);

    dbus_server_set_new_connection_function(server, new_conn, NULL, NULL);

    DBusConnection* client = dbus_connection_open_private(addr, &err);
    if (!client) { printf("client open failed: %s\n", err.message); return 1; }
    dbus_connection_set_exit_on_disconnect(client, FALSE);
    dbus_bus_register(client, &err);
    if (dbus_error_is_set(&err)) { printf("register failed: %s\n", err.message); dbus_error_free(&err); }

    /* 驱动 server 侧认证：读一次 */
    for (int i = 0; i < 50 && !g_server_conn; ++i) {
        dbus_connection_read_write(client, 20);
        if (dbus_server_get_is_connected(server) == FALSE) printf("server disconnected\n");
    }
    if (!g_server_conn) { printf("no server conn\n"); return 1; }

    /* 客户端发 8 条信号 */
    const int N = 8;
    for (int i = 0; i < N; ++i) {
        DBusMessage* m = dbus_message_new_signal("/t", "t.I", "Ping");
        dbus_uint32_t v = i;
        dbus_message_append_args(m, DBUS_TYPE_UINT32, &v, DBUS_TYPE_INVALID);
        dbus_connection_send(client, m, NULL);
        dbus_message_unref(m);
    }
    dbus_connection_flush(client);

    /* 让两条连接完成认证握手 */
    for (int i = 0; i < 40; ++i) {
        dbus_connection_read_write(g_server_conn, 10);
        dbus_connection_read_write(client, 5);
        if (dbus_connection_get_dispatch_status(g_server_conn) == DBUS_DISPATCH_DATA_REMAINS) break;
    }

    printf("[server] status after read_write = %d (DATA_REMAINS=%d)\n",
           dbus_connection_get_dispatch_status(g_server_conn), DBUS_DISPATCH_DATA_REMAINS);

    int status = dbus_connection_get_dispatch_status(g_server_conn);
    if (status != DBUS_DISPATCH_DATA_REMAINS) {
        printf("[server] no backlog constructed -> test would be vacuous\n");
        return 2;
    }

    /* 单次 read_write_dispatch */
    dbus_connection_read_write_dispatch(g_server_conn, 0);
    int after1 = dbus_connection_get_dispatch_status(g_server_conn);
    printf("[server] status after 1 dispatch = %d\n", after1);

    /* 有界清空循环 */
    int rounds = 1;
    for (; rounds < 64; ++rounds) {
        dbus_connection_read_write_dispatch(g_server_conn, 0);
        if (dbus_connection_get_dispatch_status(g_server_conn) != DBUS_DISPATCH_DATA_REMAINS) break;
    }
    printf("[server] drained after %d dispatch calls, status=%d\n",
           rounds, dbus_connection_get_dispatch_status(g_server_conn));

    dbus_connection_close(g_server_conn);
    dbus_connection_unref(g_server_conn);
    dbus_connection_close(client);
    dbus_connection_unref(client);
    dbus_free(addr);
    dbus_server_disconnect(server);
    dbus_server_unref(server);
    return 0;
}
