    for (int i = 0; i < 60; ++i) {
        dbus_connection_read_write(a, 50);
        if (dbus_connection_get_dispatch_status(a) == DBUS_DISPATCH_DATA_REMAINS) break;
    }
    int st = dbus_connection_get_dispatch_status(a);
    printf("after read-only: status=%d (REMAINS=%d) count=%d\n", st, DBUS_DISPATCH_DATA_REMAINS, g_count);
    if (st != DBUS_DISPATCH_DATA_REMAINS) { printf("NO_BACKLOG\n"); return 2; }

    dbus_connection_read_write_dispatch(a, 0);
    printf("after 1 dispatch: status=%d count=%d\n", dbus_connection_get_dispatch_status(a), g_count);

