/**
 * @brief self-pipe：signal handler 写一端，poll 循环读另一端
 *
 * 为什么用 pipe 而不是 volatile flag？
 *   dbus_connection_read_write_dispatch() 内部可能阻塞在 poll/epoll_wait 上，
 *   flag 设置后 poll 不会返回，事件循环收不到信号。
 *   pipe 写入会让 poll 的 POLLIN 立即触发，保证信号不丢失。
 *
 * 为什么 signal handler 里能用 write()？
 *   write() 是 POSIX async-signal-safe 函数，signal handler 中可以安全调用。
 *   我们只写 1 字节，几乎不会阻塞（pipe 缓冲区通常 4KB）。
 */
static int s_stop_pipe[2] = {-1, -1};

/**
 * @brief 单轮事件循环内最多派发的消息条数
 *
 * 一次 read_write_dispatch 只派发一条消息，因此这个上限等价于“单轮最多
 * 处理多少条积压消息”。取 64 的理由：
 *   - 正常负载下 libdbus 内部队列远小于此值（实测积压个位数）；
 *   - 足够小，超限回到 poll 后 self-pipe 的停止信号能被及时处理，
 *     不会拖长 systemd 停服时间。
 */
static constexpr int kMaxDispatchRounds = 64;

/**
 * @brief SIGTERM/SIGINT 处理器：写 pipe 通知 Looper 退出
 *
 * async-signal-safe 约束：只能调用 write、_exit、signal 等少数函数，
 * 严禁调用 malloc/printf/mutex_lock 等非 async-signal-safe 函数。
 * 这里只做一件事：向 pipe 写 1 字节，让 poll 立即返回。
 */
static void looper_signal_handler(int signum) {
    if (s_stop_pipe[1] >= 0) {
        char c = 1;
        (void)write(s_stop_pipe[1], &c, 1);  // 忽略返回值（pipe 满时丢弃）
    }
}

/**
 * @brief 派发 libdbus 内部队列直到清空，带轮次上限
 *
 * 为什么需要这个函数，而不是直接调一次 read_write_dispatch？
 *   dbus_connection_read_write_dispatch 的语义是"读一次 + 派发**一条**消息"
 *   （实测：队列有 8 条积压时，一次调用只让回调计数 +1，dispatch_status
 *   仍是 DBUS_DISPATCH_DATA_REMAINS）。只有反复调用才能清空队列。
 *
 * 为什么不能写成无界 while？
 *   dbus_connection_read_write_dispatch 的返回值语义是"连接未断开"而不是
 *   "还有数据"。持续有内部消息时会永久饿死 self-pipe 的停止信号，导致
 *   SIGTERM/SIGINT 失效（systemd 停服只能等 TimeoutStopSec 后 SIGKILL），
 *   主线程空转、单核 CPU 接近 100%。
 *
 * @param conn       D-Bus 连接
 * @param max_rounds 最多派发轮次；正常负载下队列远小于此值
 * @return false 表示连接已断开，调用方应退出主循环
 */
static bool dispatch_until_drained(DBusConnection* conn, int max_rounds) {
    for (int round = 0; round < max_rounds; ++round) {
        if (!dbus_connection_read_write_dispatch(conn, 0)) return false;
        if (dbus_connection_get_dispatch_status(conn) != DBUS_DISPATCH_DATA_REMAINS) {
            return true;  // 队列已清空
        }
    }
    return true;
}

