/**
 * @file test_looper_dispatch_gtest.cpp
 * @brief Looper D-Bus 派发层行为的回归测试
 *
 * 背景（2026-11-01 修复的缺陷）：
 *   looper.cpp 原先在每次 poll 唤醒后只调用一次
 *   dbus_connection_read_write_dispatch(conn_, 0)，注释声称
 *   “若仍有数据到达，poll 会立即再次唤醒”。这个假设有两半都不成立：
 *
 *   1. 单次 read_write_dispatch 只派发**一条**消息（本测试 Test 1 实测断言），
 *      队列积压时要排队等后续轮次；
 *   2. 内部队列有积压但 socket 已读空时，poll **不再**报告 POLLIN
 *      （本测试 Test 3 实测断言），积压只能等下一条 socket 数据。
 *
 *   现场症状：GetInterfaces 延迟呈 13ms / 300ms / 1000ms / 3000ms 的离散阶梯，
 *   最坏 25s；而服务端日志时间戳证明延迟全部产生在 handleXxx 被调用之前
 *   （派发层排队），处理逻辑本身耗时近零。
 *
 * 修复（server/src/looper.cpp 的 dispatch_until_drained）：
 *   每轮事件循环派发到 DBUS_DISPATCH_COMPLETE，且上限 64 轮防止饿死
 *   self-pipe 的停止信号；poll 超时但队列仍有积压时也主动排空。
 *
 * 测试隔离性：
 *   本套件不依赖环境里已有的会话总线（CI 与开发板上都没有），而是自己拉起
 *   一个 `dbus-daemon --session --nofork` 子进程，用完即杀。若连 dbus-daemon
 *   都不可用，测试显式 SKIP 并打印原因，绝不伪通过。
 */

#include <gtest/gtest.h>

#include <dbus/dbus.h>
#include <poll.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

#include <cerrno>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>

namespace {

/// 与 looper.cpp 的 kMaxDispatchRounds 保持同值（本测试会断言该上限的语义）
constexpr int kMaxDispatchRounds = 64;

/**
 * @brief 一次性拉起私有 dbus-daemon，提供不依赖环境的测试总线
 *
 * 为什么不用 DBUS_BUS_SESSION？
 *   CI（GitHub Actions）与开发板（systemd 服务）都没有会话总线，
 *   `dbus_bus_get_private(DBUS_BUS_SESSION)` 会失败，测试只能 SKIP——
 *   一条永远被跳过的回归测试等于没有回归测试。
 */
class PrivateBus {
public:
    PrivateBus() {
        int out[2];
        if (pipe(out) != 0) {
            reason_ = std::string("pipe() failed: ") + std::strerror(errno);
            return;
        }

        pid_ = fork();
        if (pid_ < 0) {
            reason_ = std::string("fork() failed: ") + std::strerror(errno);
            ::close(out[0]);
            ::close(out[1]);
            return;
        }

        if (pid_ == 0) {
            // 子进程：把 stdout 指向管道写端，--print-address=1 会把地址打到 stdout
            dup2(out[1], STDOUT_FILENO);
            ::close(out[0]);
            ::close(out[1]);
            // 忽略 SIGPIPE：父进程提前关闭管道时不要被杀死
            signal(SIGPIPE, SIG_IGN);
            execlp("dbus-daemon", "dbus-daemon", "--session", "--nofork",
                   "--print-address=1", static_cast<char*>(nullptr));
            _exit(127);  // execlp 失败
        }

        ::close(out[1]);
        // 读一行地址（最多等 5 秒）
        char buf[512];
        std::string line;
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
        while (std::chrono::steady_clock::now() < deadline) {
            const ssize_t n = ::read(out[0], buf, sizeof(buf));
            if (n > 0) {
                line.append(buf, static_cast<size_t>(n));
                const auto nl = line.find('\n');
                if (nl != std::string::npos) {
                    line.resize(nl);
                    break;
                }
            } else if (n == 0) {
                break;
            } else if (errno != EINTR) {
                break;
            }
        }
        ::close(out[0]);

        if (line.empty()) {
            reason_ = "dbus-daemon 未输出总线地址（未安装或启动失败）";
            killDaemon();
            return;
        }
        address_ = line;
    }

    ~PrivateBus() {
        killDaemon();
    }

    PrivateBus(const PrivateBus&) = delete;
    PrivateBus& operator=(const PrivateBus&) = delete;

    bool ok() const { return !address_.empty() && pid_ > 0; }
    const std::string& address() const { return address_; }
    const std::string& reason() const { return reason_; }

private:
    void killDaemon() {
        if (pid_ > 0) {
            ::kill(pid_, SIGTERM);
            int status = 0;
            // 最多等 2 秒，超时用 SIGKILL 兜底，避免僵尸进程拖住测试
            for (int i = 0; i < 20; ++i) {
                if (::waitpid(pid_, &status, WNOHANG) == pid_) {
                    pid_ = -1;
                    return;
                }
