int buildBacklog(DBusConnection* connA, DBusConnection* connB, int n, int* base_count) {
    const char* dest = dbus_bus_get_unique_name(connA);
    if (!dest) return 0;

    for (int i = 0; i < n; ++i) {
        DBusMessage* msg = dbus_message_new_signal("/com/example/WeakNet/Test",
                                                   "com.example.WeakNet.Test", "Ping");
        if (!msg) return 0;
        dbus_uint32_t seq = static_cast<dbus_uint32_t>(i);
        dbus_message_append_args(msg, DBUS_TYPE_UINT32, &seq, DBUS_TYPE_INVALID);
        dbus_message_set_destination(msg, dest);
        dbus_connection_send(connB, msg, nullptr);
        dbus_message_unref(msg);
    }
    dbus_connection_flush(connB);

    // 只读（read_write）不派发（dispatch）：消息进入 libdbus 内部队列
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
    while (std::chrono::steady_clock::now() < deadline) {
        dbus_connection_read_write(connA, 20);
        if (dbus_connection_get_dispatch_status(connA) == DBUS_DISPATCH_DATA_REMAINS) {
            break;
        }
    }
    if (dbus_connection_get_dispatch_status(connA) != DBUS_DISPATCH_DATA_REMAINS) {
        return 0;  // 没能构造出积压
    }
    *base_count = 0;
    dbus_connection_add_filter(connA, countSignals, base_count, nullptr);
    return n;
