/**
 * @file test_looper_dispatch_gtest.cpp
 * @brief Looper D-Bus 派发层行为的回归测试
 *
 * 背景（2026-11-01 修复的缺陷）：
 *   looper.cpp 原先在每次 poll 唤醒后只调用一次
 *   dbus_connection_read_write_dispatch(conn_, 0)，注释声称
 *   “若仍有数据到达，poll 会立即再次唤醒”。这个假设有两半都不成立：
 *
 *   1. 单次 read_write_dispatch 只派发**一条**消息（本测试 Test 2 断言），
 *      队列积压时要排队等后续轮次；
 *   2. 内部队列有积压但 socket 已读空时，poll **不再**报告 POLLIN
 *      （本测试 Test 3 断言），积压只能等下一条 socket 数据。
 *
 *   现场症状：GetInterfaces 延迟呈 13ms / 300ms / 1000ms / 3000ms 的离散阶梯，
 *   最坏 25s；而服务端日志时间戳证明延迟全部产生在 handleXxx 被调用之前
 *   （派发层排队），处理逻辑本身耗时近零。
 *
 * 修复（server/src/looper.cpp 的 dispatch_until_drained）：
 *   每轮事件循环派发到 DBUS_DISPATCH_COMPLETE，上限 64 轮防止饿死
 *   self-pipe 的停止信号；poll 超时但队列仍有积压时也主动排空。
 *
 * 测试隔离性：
 *   本套件不依赖环境里已有的会话总线（CI 与开发板上都没有），而是自己拉起
 *   一个 `dbus-daemon --session --nofork` 子进程，用完即杀。若连 dbus-daemon
 *   都不可用，测试显式 SKIP 并打印原因，绝不伪通过。
 */

#include <gtest/gtest.h>

#include <dbus/dbus.h>
#include <poll.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

#include <cerrno>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>

namespace {

/// 与 looper.cpp 的 kMaxDispatchRounds 保持同值（Test 4 断言该上限的语义）
constexpr int kMaxDispatchRounds = 64;

/**
 * @brief 一次性拉起私有 dbus-daemon，提供不依赖环境的测试总线
 *
 * 为什么不用 DBUS_BUS_SESSION？
 *   CI（GitHub Actions）与开发板（systemd 服务）都没有会话总线，
 *   `dbus_bus_get_private(DBUS_BUS_SESSION)` 会失败，测试只能 SKIP——
 *   一条永远被跳过的回归测试等于没有回归测试。
 */
class PrivateBus {
public:
    PrivateBus() {
        int out[2];
        if (pipe(out) != 0) {
            reason_ = std::string("pipe() failed: ") + std::strerror(errno);
            return;
        }

        pid_ = fork();
        if (pid_ < 0) {
            reason_ = std::string("fork() failed: ") + std::strerror(errno);
            ::close(out[0]);
            ::close(out[1]);
            return;
        }

        if (pid_ == 0) {
            // 子进程：把 stdout 指向管道写端，--print-address=1 会把地址打到 stdout
            dup2(out[1], STDOUT_FILENO);
            ::close(out[0]);
            ::close(out[1]);
            // 忽略 SIGPIPE：父进程提前关闭管道时不要被杀死
            signal(SIGPIPE, SIG_IGN);
            execlp("dbus-daemon", "dbus-daemon", "--session", "--nofork",
                   "--print-address=1", static_cast<char*>(nullptr));
            _exit(127);  // execlp 失败
        }

        ::close(out[1]);
        // 读一行地址（最多等 5 秒）
        char buf[512];
        std::string line;
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
        while (std::chrono::steady_clock::now() < deadline) {
            const ssize_t n = ::read(out[0], buf, sizeof(buf));
            if (n > 0) {
                line.append(buf, static_cast<size_t>(n));
                const auto nl = line.find('\n');
                if (nl != std::string::npos) {
                    line.resize(nl);
                    break;
                }
            } else if (n == 0) {
                break;
            } else if (errno != EINTR) {
                break;
            }
        }
        ::close(out[0]);

        if (line.empty()) {
            reason_ = "dbus-daemon 未输出总线地址（未安装或启动失败）";
            killDaemon();
            return;
        }
        address_ = line;
    }

    ~PrivateBus() { killDaemon(); }

    PrivateBus(const PrivateBus&) = delete;
    PrivateBus& operator=(const PrivateBus&) = delete;

    bool ok() const { return !address_.empty() && pid_ > 0; }
    const std::string& address() const { return address_; }
    const std::string& reason() const { return reason_; }

private:
    void killDaemon() {
        if (pid_ > 0) {
            ::kill(pid_, SIGTERM);
            int status = 0;
            // 最多等 2 秒，超时用 SIGKILL 兜底，避免僵尸进程拖住测试
            for (int i = 0; i < 20; ++i) {
                if (::waitpid(pid_, &status, WNOHANG) == pid_) {
                    pid_ = -1;
                    return;
                }
                ::usleep(100 * 1000);
            }
            ::kill(pid_, SIGKILL);
            (void)::waitpid(pid_, &status, 0);
            pid_ = -1;
        }
    }

    pid_t pid_ = -1;
    std::string address_;
    std::string reason_;
};

/// 打开一条私有连接并完成注册，返回唯一名（用于定向发送的单播消息）
DBusConnection* openPrivate(const std::string& address, std::string* unique_name) {
    DBusError err;
    dbus_error_init(&err);
    DBusConnection* c = dbus_connection_open_private(address.c_str(), &err);
    if (!c) {
        dbus_error_free(&err);
        return nullptr;
    }
    dbus_connection_set_exit_on_disconnect(c, FALSE);
    if (!dbus_bus_register(c, &err)) {
        dbus_error_free(&err);
        dbus_connection_close(c);
        dbus_connection_unref(c);
        return nullptr;
    }
    if (unique_name) {
        const char* n = dbus_bus_get_unique_name(c);
        *unique_name = n ? n : "";
    }
    return c;
}

void closePrivate(DBusConnection* c) {
    if (!c) return;
    dbus_connection_close(c);
    dbus_connection_unref(c);
}

/// 统计收到的信号条数（filter 在所有消息上调用，含非信号消息，故只计信号）
DBusHandlerResult countSignals(DBusConnection* conn, DBusMessage* msg, void* data) {
    (void)conn;
    int* count = static_cast<int*>(data);
    if (dbus_message_get_type(msg) == DBUS_MESSAGE_TYPE_SIGNAL) {
        ++(*count);
    }
    return DBUS_HANDLER_RESULT_HANDLED;
}

/**
 * @brief 向 connA 定向发送 n 条信号，然后只读不派发，制造 libdbus 内部积压
 *
 * 用单播（destination = connA 的唯一名）而不是广播 + match 规则，
 * 这样不需要额外注册 match，行为完全确定。
 *
 * @param base_count 出去时通过它回填“构造积压前已收到的信号数”
 * @return 实际构造出的积压条数；0 表示构造失败（测试应当 SKIP 而非伪通过）
 */
int buildBacklog(DBusConnection* connA, DBusConnection* connB, int n, int* base_count) {
    const char* dest = dbus_bus_get_unique_name(connA);
    if (!dest) return 0;

    for (int i = 0; i < n; ++i) {
        DBusMessage* msg = dbus_message_new_signal("/com/example/WeakNet/Test",
                                                   "com.example.WeakNet.Test", "Ping");
        if (!msg) return 0;
        dbus_uint32_t seq = static_cast<dbus_uint32_t>(i);
        dbus_message_append_args(msg, DBUS_TYPE_UINT32, &seq, DBUS_TYPE_INVALID);
        dbus_message_set_destination(msg, dest);
        dbus_connection_send(connB, msg, nullptr);
        dbus_message_unref(msg);
    }
    dbus_connection_flush(connB);

    // 只读不派发：把字节搬进 libdbus 内部队列，使 dispatch_status 变为 DATA_REMAINS。
    // 注意：一旦 libdbus 把消息从 socket 读入内部队列，socket 就不再可读——
    // 这正是 looper.cpp 必须“主动排空”而非“等 POLLIN”的原因（Test 3 直接验证）。
    int guard = 0;
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
    while (std::chrono::steady_clock::now() < deadline) {
        dbus_connection_read_write(connA, 10);
        if (dbus_connection_get_dispatch_status(connA) == DBUS_DISPATCH_DATA_REMAINS) break;
        ++guard;
    }
    (void)guard;

    if (dbus_connection_get_dispatch_status(connA) != DBUS_DISPATCH_DATA_REMAINS) return 0;

    // 记录构造阶段的计数（filter 在这期间不应被调用，因为还没派发）
    *base_count = 0;
    return n;
}

}  // namespace

/**
 * @brief 契约 1：私有总线可用（其余用例的前置）
 *
 * 单独成一个用例，是为了让“环境缺 dbus-daemon”与“派发语义变更”在报告里
 * 可区分：前者 SKIP，后者 FAIL。
 */
TEST(LooperDispatchTest, PrivateBusIsAvailable) {
    PrivateBus bus;
    if (!bus.ok()) {
        GTEST_SKIP() << "无法启动私有 dbus-daemon，跳过: " << bus.reason();
    }
    EXPECT_FALSE(bus.address().empty());
}

/**
 * @brief 契约 2：一次 read_write_dispatch 只派发一条消息
 *
 * 这是修复的直接依据。若将来 libdbus 语义变成“一次派发全部”，本用例会
 * 失败——那说明 looper.cpp 的循环上限可以放宽，但**不能**据此认为旧代码没问题。
 *
 * 断言：积压 N 条时，一次调用后 filter 只被调用一次且状态仍为 DATA_REMAINS。
 */
TEST(LooperDispatchTest, SingleDispatchHandlesOnlyOneMessage) {
    PrivateBus bus;
    if (!bus.ok()) {
        GTEST_SKIP() << "无法启动私有 dbus-daemon，跳过: " << bus.reason();
    }

    std::string nameA, nameB;
    DBusConnection* connA = openPrivate(bus.address(), &nameA);
    DBusConnection* connB = openPrivate(bus.address(), &nameB);
    ASSERT_NE(connA, nullptr);
    ASSERT_NE(connB, nullptr);

    int count = 0;
    dbus_connection_add_filter(connA, countSignals, &count, nullptr);

    constexpr int kMessages = 8;
    int base = 0;
    const int queued = buildBacklog(connA, connB, kMessages, &base);
    if (queued == 0) {
        closePrivate(connA);
        closePrivate(connB);
        GTEST_SKIP() << "未能构造出 libdbus 内部积压，跳过（不伪通过）";
    }

    dbus_connection_read_write_dispatch(connA, 0);

    EXPECT_EQ(count, 1) << "单次 read_write_dispatch 应只派发一条消息";
    EXPECT_EQ(dbus_connection_get_dispatch_status(connA), DBUS_DISPATCH_DATA_REMAINS)
        << "8 条积压只处理了 1 条，队列应仍为 DATA_REMAINS";

    closePrivate(connA);
    closePrivate(connB);
}

/**
 * @brief 契约 3：内部队列积压时 poll 不再报告 POLLIN
 *
 * 这是“必须主动排空”的直接依据。旧代码只在 POLLIN 分支派发，一旦积压
 * 就再也等不到 POLLIN，只能靠下一条 socket 数据搭车——这正是 300ms /
 * 1000ms / 3000ms 阶梯延迟的来源。
 */
