    p.fd = fd;
    p.events = POLLIN;
    const int ret = poll(&p, 1, 300);

    EXPECT_EQ(ret, 0) << "内部队列有积压时 poll 不应报告 POLLIN（revents=0x"
                      << std::hex << p.revents << "）；若此处失败说明 libdbus 语义已变，"
                      << "需重新评估 looper.cpp 的主动排空逻辑";
    EXPECT_EQ(count, 0) << "未派发前 filter 不应被调用";

    closePrivate(connA);
    closePrivate(connB);
}

