59	class PrivateBus {
60	public:
61	    PrivateBus() {
62	        int out[2];
63	        if (pipe(out) != 0) {
64	            reason_ = std::string("pipe() failed: ") + std::strerror(errno);
65	            return;
66	        }
67	
68	        pid_ = fork();
69	        if (pid_ < 0) {
70	            reason_ = std::string("fork() failed: ") + std::strerror(errno);
71	            ::close(out[0]);
72	            ::close(out[1]);
73	            return;
74	        }
75	
76	        if (pid_ == 0) {
77	            // 子进程：把 stdout 指向管道写端，--print-address=1 把地址打到 stdout
78	            dup2(out[1], STDOUT_FILENO);
79	            ::close(out[0]);
80	            ::close(out[1]);
81	            signal(SIGPIPE, SIG_IGN);  // 父进程提前关管道时不要被杀死
82	            execlp("dbus-daemon", "dbus-daemon", "--session", "--nofork",
83	                   "--print-address=1", static_cast<char*>(nullptr));
84	            _exit(127);  // execlp 失败
85	        }
86	
87	        ::close(out[1]);
88	        // 读一行地址（最多等 5 秒）
89	        char buf[512];
90	        std::string line;
91	        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
92	        while (std::chrono::steady_clock::now() < deadline) {
93	            const ssize_t n = ::read(out[0], buf, sizeof(buf));
94	            if (n > 0) {
95	                line.append(buf, static_cast<size_t>(n));
96	                const auto nl = line.find('\n');
97	                if (nl != std::string::npos) {
98	                    line.resize(nl);
99	                    break;
100	                }
101	            } else if (n == 0) {
102	                break;
103	            } else if (errno != EINTR) {
104	                break;
105	            }
106	        }
107	        ::close(out[0]);
108	
109	        if (line.empty()) {
110	            reason_ = "dbus-daemon 未输出总线地址（未安装或启动失败）";
111	            killDaemon();
112	            return;
113	        }
114	        address_ = line;
115	    }
