120	    PrivateBus& operator=(const PrivateBus&) = delete;
121	
122	    bool ok() const { return !address_.empty() && pid_ > 0; }
123	    const std::string& address() const { return address_; }
124	    const std::string& reason() const { return reason_; }
125	
126	private:
127	    void killDaemon() {
128	        if (pid_ > 0) {
129	            ::kill(pid_, SIGTERM);
130	            int status = 0;
131	            // 最多等 2 秒，超时用 SIGKILL 兜底，避免僵尸进程拖住测试
132	            for (int i = 0; i < 20; ++i) {
133	                if (::waitpid(pid_, &status, WNOHANG) == pid_) {
134	                    pid_ = -1;
135	                    return;
136	                }
137	                ::usleep(100 * 1000);
138	            }
139	            ::kill(pid_, SIGKILL);
140	            (void)::waitpid(pid_, &status, 0);
141	            pid_ = -1;
142	        }
143	    }
144	
145	    pid_t pid_ = -1;
146	    std::string address_;
147	    std::string reason_;
148	};
