/* 复用一条 D-Bus 连接连续调用，测服务端真实处理延迟（不含进程启动开销） */
#include <dbus/dbus.h>
#include <stdio.h>
#include <time.h>

static double now_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000.0 + ts.tv_nsec / 1e6;
}

int main(int argc, char** argv) {
