    DBusConnection* c = dbus_bus_get_private(DBUS_BUS_SYSTEM, &err);
    if (!c) { fprintf(stderr, "connect failed: %s\n", err.message); return 1; }
    dbus_connection_set_exit_on_disconnect(c, FALSE);

