            "com.example.WeakNet", method);
        if (!msg) { fails++; continue; }
        double t0 = now_ms();
        DBusMessage* reply = dbus_connection_send_with_reply_and_block(c, msg, 5000, &err);
        double t1 = now_ms();
        dbus_message_unref(msg);
        if (!reply) { fails++; dbus_error_free(&err); continue; }
        dbus_message_unref(reply);
        lat[i - fails >= 0 ? i - fails : 0] = t1 - t0;
    }
    int n = N - fails;
    /* 简单插入排序取分位 */
    for (int i = 1; i < n; ++i) {
        double k = lat[i]; int j = i - 1;
        while (j >= 0 && lat[j] > k) { lat[j+1] = lat[j]; j--; }
        lat[j+1] = k;
    }
    printf("%-24s n=%-4d p50=%6.2f p95=%6.2f p99=%6.2f max=%6.2f fails=%d\n",
           method, n, lat[n/2], lat[(int)(n*0.95)], lat[(int)(n*0.99)], lat[n-1], fails);
    dbus_connection_close(c); dbus_connection_unref(c);
    return 0;
}
