cd /tmp && cat > stress_backlog.c <<'EOF'
/* 极端积压压测：构造 N 条待派发消息，验证 dispatchUntilDrained 的行为
 *
 * 目标：
 *   1. 1000+ 条积压时，单轮排空需要多少轮（是否远小于 64 上限）
 *   2. 超过 64 上限时，剩余积压能否在后续轮次继续推进（不会永久卡住）
 *   3. 排空过程本身耗时（不能让主循环单次阻塞过久）
 */
#include <dbus/dbus.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

static double now_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000.0 + ts.tv_nsec / 1e6;
}

static int g_count = 0;
static DBusHandlerResult cnt(DBusConnection* c, DBusMessage* m, void* d) {
    (void)c; (void)d;
    if (dbus_message_get_type(m) == DBUS_MESSAGE_TYPE_SIGNAL) {
        const char* i = dbus_message_get_interface(m);
        if (i && strcmp(i, "com.example.WeakNet.Stress") == 0) g_count++;
    }
    return DBUS_HANDLER_RESULT_HANDLED;
}

/* 与 looper.cpp 的 dispatchUntilDrained 完全一致 */
static int dispatch_until_drained(DBusConnection* conn, int max_rounds) {
    int rounds = 0;
    for (; rounds < max_rounds; ++rounds) {
        if (!dbus_connection_read_write_dispatch(conn, 0)) return -1;
        if (dbus_connection_get_dispatch_status(conn) != DBUS_DISPATCH_DATA_REMAINS)
            return rounds + 1;
    }
    return rounds;  /* 达到上限仍未清空 */
}

static void read_all_into_queue(DBusConnection* conn) {
    int fd = -1;
    if (!dbus_connection_get_socket(conn, &fd) || fd < 0) return;
    struct pollfd p;
    for (int i = 0; i < 500; ++i) {
        p.fd = fd; p.events = POLLIN; p.revents = 0;
        if (poll(&p, 1, 20) == 0) return;
        dbus_connection_read_write(conn, 0);
    }
}

int main(int argc, char** argv) {
    int N = argc > 1 ? atoi(argv[1]) : 1000;
    DBusError err; dbus_error_init(&err);

    DBusConnection* a = dbus_bus_get_private(DBUS_BUS_SYSTEM, &err);
    DBusConnection* b = dbus_bus_get_private(DBUS_BUS_SYSTEM, &err);
    if (!a || !b) { printf("connect failed: %s\n", err.message ? err.message : "?"); return 1; }
    dbus_connection_set_exit_on_disconnect(a, FALSE);
    dbus_connection_set_exit_on_disconnect(b, FALSE);
    dbus_connection_add_filter(a, cnt, NULL, NULL);

    /* 清空握手噪声 */
    for (int i = 0; i < 64; ++i) {
        dbus_connection_read_write_dispatch(a, 0);
        if (dbus_connection_get_dispatch_status(a) != DBUS_DISPATCH_DATA_REMAINS) break;
    }
    g_count = 0;

    const char* dest = dbus_bus_get_unique_name(a);
    double t_send = now_ms();
    for (int i = 0; i < N; ++i) {
        DBusMessage* m = dbus_message_new_signal("/stress", "com.example.WeakNet.Stress", "Burst");
        dbus_uint32_t seq = (dbus_uint32_t)i;
        dbus_message_append_args(m, DBUS_TYPE_UINT32, &seq, DBUS_TYPE_INVALID);
        dbus_message_set_destination(m, dest);
        dbus_connection_send(b, m, NULL);
        dbus_message_unref(m);
    }
    dbus_connection_flush(b);
    t_send = now_ms() - t_send;

    read_all_into_queue(a);
    printf("N=%d 发送耗时=%.1fms 队列状态=%d(REMAINS=%d)\n",
           N, t_send, dbus_connection_get_dispatch_status(a), DBUS_DISPATCH_DATA_REMAINS);

    /* 单轮（上限 64）排空 */
    double t0 = now_ms();
    int r1 = dispatch_until_drained(a, 64);
    double d1 = now_ms() - t0;
    printf("第1轮上限64: rounds=%d 处理=%d 耗时=%.2fms 剩余状态=%d\n",
           r1, g_count, d1, dbus_connection_get_dispatch_status(a));

    /* 后续轮次继续推进，最多再跑 200 轮模拟主循环 */
    int total_rounds = (r1 > 0 ? r1 : 0);
    int extra_cycles = 0;
    double t_all = now_ms();
    while (dbus_connection_get_dispatch_status(a) == DBUS_DISPATCH_DATA_REMAINS
           && extra_cycles < 200) {
        int r = dispatch_until_drained(a, 64);
        if (r <= 0) break;
        total_rounds += r;
        extra_cycles++;
    }
    double d_all = now_ms() - t_all;

    printf("继续推进: 额外循环=%d 总rounds=%d 总处理=%d/%d 耗时=%.2fms 最终状态=%d\n",
           extra_cycles, total_rounds, g_count, N, d_all,
           dbus_connection_get_dispatch_status(a));

    int rc = 0;
    if (g_count != N) { printf("FAIL: 只处理 %d/%d\n", g_count, N); rc = 1; }
    if (d1 > 50.0)    { printf("FAIL: 单轮耗时 %.2fms 超过 50ms\n", d1); rc = 1; }
    if (dbus_connection_get_dispatch_status(a) == DBUS_DISPATCH_DATA_REMAINS) {
        printf("FAIL: 积压未清空\n"); rc = 1;
    }

    dbus_connection_close(a); dbus_connection_unref(a);
    dbus_connection_close(b); dbus_connection_unref(b);
    printf(rc == 0 ? "RESULT: PASS\n" : "RESULT: FAIL\n");
    return rc;
}
EOF
